test "countOccurrences" {
    const input = "pub fn a() pub fn b() pub fn c()";
    try std.testing.expectEqual(@as(usize, 3), countOccurrences(input, "pub fn "));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences("no matches", "pub fn "));
}

test "countLines" {
    try std.testing.expectEqual(@as(usize, 1), countLines("single"));
    try std.testing.expectEqual(@as(usize, 3), countLines("a\nb\nc"));
}

test "isIdent" {
    try std.testing.expect(isIdent('a'));
    try std.testing.expect(isIdent('Z'));
    try std.testing.expect(isIdent('_'));
    try std.testing.expect(!isIdent(' '));
}

test "relativePath" {
    try std.testing.expectEqualStrings(
        "api/core.zig",
        relativePath("/home/user/project/src/api/core.zig", "/home/user/project/src"),
    );
    try std.testing.expectEqualStrings(
        "src/main.zig",
        relativePath("/foo/bar/src/main.zig", "/other/path"),
    );
}

test "ImportGraph.isSkippableDir skips dot-prefixed directories" {
    // Hardcoded skip list must still match.
    try std.testing.expect(ImportGraph.isSkippableDir(".git"));
    try std.testing.expect(ImportGraph.isSkippableDir("zig-out"));
    try std.testing.expect(ImportGraph.isSkippableDir("node_modules"));
    try std.testing.expect(ImportGraph.isSkippableDir("vendor"));

    // Regression: any dot-prefixed dir must be skipped. direnv-per-project
    // caches and project-local scratch dirs previously caused recursive
    // traversals to walk thousands of cache entries.
    try std.testing.expect(ImportGraph.isSkippableDir(".zig-global-cache"));
    try std.testing.expect(ImportGraph.isSkippableDir(".zig-cache-ephor"));
    try std.testing.expect(ImportGraph.isSkippableDir(".zig-cache-test"));
    try std.testing.expect(ImportGraph.isSkippableDir(".tmp"));
    try std.testing.expect(ImportGraph.isSkippableDir(".claude"));

    // Non-hidden, non-listed dirs must still be traversable.
    try std.testing.expect(!ImportGraph.isSkippableDir("src"));
    try std.testing.expect(!ImportGraph.isSkippableDir("lib"));
    try std.testing.expect(!ImportGraph.isSkippableDir("tests"));
}

// ============================================================================
// Phase 4: CFG Memory Analysis Tests (ZA105, ZA106)
// ============================================================================

/// Helper to create test FileAnalysis with content
fn createTestFileAnalysis(
    allocator: Allocator,
    path: []const u8,
    content: []const u8,
) !FileAnalysis {
    const path_copy = try allocator.dupe(u8, path);
    return .{
        .path = path_copy,
        .resolved_path = path_copy,
        .imports = .empty,
        .content = try allocator.dupe(u8, content),
        .has_tests = false,
        .pub_function_count = 0,
        .line_count = countLines(content),
    };
}

/// Graph + issues from running the CFG memory pipeline on one in-memory file.
const CFGTestRun = struct {
    graph: ImportGraph,
    issues: std.ArrayListUnmanaged(Issue),

    fn deinit(self: *CFGTestRun, allocator: Allocator) void {
        self.graph.deinit();
        deinitIssues(&self.issues, allocator);
    }
};

/// Test helper: build a one-file graph and run the full CFG memory pipeline.
fn runCFGMemoryTest(
    allocator: Allocator,
    path: []const u8,
    content: []const u8,
) !CFGTestRun {
    var graph = ImportGraph.init(allocator);
    errdefer graph.deinit();
    const analysis = try createTestFileAnalysis(allocator, path, content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, path), {});
    var issues = try analyzeCFGMemory(allocator, &graph);
    errdefer deinitIssues(&issues, allocator);
    return .{ .graph = graph, .issues = issues };
}

/// Count issues for a rule within one file (test assertion helper).
fn countRuleIssues(
    issues: []const Issue,
    file: []const u8,
    rule: []const u8,
) usize {
    var n: usize = 0;
    for (issues) |issue| {
        if (mem.eql(u8, issue.file, file) and mem.eql(u8, issue.rule, rule)) n += 1;
    }
    return n;
}

test "ZA101/ZA103: multi-line .alloc( with wrapped args is detected" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // zig-fmt canonical wrap: first line ends after `(` — the type first-arg
    // only becomes visible by joining continuation lines.
    const content =
        \\fn wrapped_alloc(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(
        \\        u8,
        \\        4096,
        \\    );
        \\    const more = try allocator.alloc(u8, 64);
        \\    _ = more;
        \\    _ = buf;
        \\}
    ;
    var run = try runCFGMemoryTest(allocator, "test_wrapped_alloc.zig", content);
    defer run.deinit(allocator);

    const file = "test_wrapped_alloc.zig";
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_DEFER) >= 1);
    // Second try with no errdefer on either alloc => errdefer gap tracked
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_ERRDEFER) >= 1);
}

test "ZA101: single-line .alloc( detection unchanged by line joining" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const content =
        \\fn single_line(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 4096);
        \\    _ = buf;
        \\}
    ;
    var run = try runCFGMemoryTest(allocator, "test_single_alloc.zig", content);
    defer run.deinit(allocator);

    try std.testing.expect(countRuleIssues(
        run.issues.items,
        "test_single_alloc.zig",
        RULE_ALLOC_NO_DEFER,
    ) == 1);
}

test "ZA101: wrapped alloc with proper defer stays silent" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const content =
        \\fn wrapped_ok(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(
        \\        u8,
        \\        4096,
        \\    );
        \\    defer allocator.free(buf);
        \\    _ = buf;
        \\}
    ;
    var run = try runCFGMemoryTest(allocator, "test_wrapped_ok.zig", content);
    defer run.deinit(allocator);

    const file = "test_wrapped_ok.zig";
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_DEFER) == 0);
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_USE_AFTER_FREE) == 0);
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_DOUBLE_FREE) == 0);
}

test "ZA105: free through alias then use root" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Freeing an alias releases the root allocation: use of buf is UAF.
    const content =
        \\fn free_alias_use_root(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\    const a = buf;
        \\    allocator.free(a);
        \\    use(buf);
        \\}
        \\fn use(d: []u8) void {
        \\    _ = d;
        \\}
    ;
    var run = try runCFGMemoryTest(allocator, "test_free_alias_use.zig", content);
    defer run.deinit(allocator);

    try std.testing.expect(countRuleIssues(
        run.issues.items,
        "test_free_alias_use.zig",
        RULE_USE_AFTER_FREE,
    ) == 1);
}

test "ZA106: free through alias then free root" {
    var gpa = std.heap.DebugAllocator(.{}){};
