    const content =
        \\fn free_reassign(allocator: std.mem.Allocator) !void {
        \\    var buf = try allocator.alloc(u8, 64);
        \\    allocator.free(buf);
        \\    buf = try allocator.alloc(u8, 128);
        \\    use(buf);
        \\}
        \\fn use(d: []u8) void {
        \\    _ = d;
        \\}
