test "Config.isRuleEnabled respects disable prefix" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var cfg = Config{
        .command = .check,
        .path = "src",
        .path_owned = false,
        .entries = .empty,
        .exclude = .empty,
        .orphan_exclude = .empty,
