        \\fn doWork() void {}
        \\fn f() void {
        \\    mu.lock();
        \\    // defer mu.unlock();
        \\    doWork();
        \\    const s = "mu.unlock(); mu.lock();";
        \\    _ = s;
        \\    // mu.lock();
        \\}
    ;
    var run = try runConcurrencyCheck(allocator, "zc101_strings.zig", content);
    defer run.deinit(allocator);

    try expectZC101Counts(run.issues.items, 1, 0);
}

