    const content =
        \\fn doWork() void {}
        \\fn f(c: bool) void {
        \\    if (c) {
        \\        mu.lock();
        \\        doWork();
        \\    } else {
        \\        mu.lock();
        \\        doWork();
        \\    }
        \\    mu.unlock();
        \\}
