    // sibling prong, not a sequential block.
    const content =
        \\fn f(x: u8) void {
        \\    switch (x) {
        \\        0 => {
        \\            mu.lock();
        \\        },
        \\        else => {
        \\            mu.lock();
        \\        },
        \\    }
        \\    mu.unlock();
        \\}
    ;
