test "ZC104: field-stored handle never joined still warns" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Control for the alias fallback: `self.thread` with no join anywhere
    // must NOT be vacuously suppressed by the last-segment search.
    const content =
        \\fn work() void {}
        \\fn start(self: *S) !void {
        \\    self.thread = try std.Thread.spawn(.{}, work, .{});
        \\}
        \\fn stop(self: *S) void {
        \\    self.running = false;
        \\}
    ;
    var run = try runConcurrencyCheck(allocator, "zc104_fieldwarn.zig", content);
    defer run.deinit(allocator);

    try expectZC104Counts(run.issues.items, 1, 0);
}

test "ZC104: optional handle joined with .?.join() is silent" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // messenger dht_kademlia_ops: `worker.thread = spawn(...) catch ...`
    // with the join as `worker.thread.?.join()` on the ?std.Thread field.
    const content =
        \\fn work() void {}
        \\fn spawnIt(worker: *W) void {
        \\    worker.thread = std.Thread.spawn(.{}, work, .{worker}) catch return;
        \\    worker.spawned = true;
        \\}
        \\fn joinIt(worker: *W) void {
        \\    if (worker.spawned) worker.thread.?.join();
        \\}
    ;
    var run = try runConcurrencyCheck(allocator, "zc104_optjoin.zig", content);
    defer run.deinit(allocator);

    try expectZC104Counts(run.issues.items, 0, 0);
}

test "ZC104: struct-literal field init is an ownership transfer (mach alsa)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // `.thread = std.Thread.spawn(...)` inside an anonymous struct
    // literal: the constructed value owns the handle (the join lives on
    // the receiver: watcher.thread.join()).
    const content =
        \\fn work() void {}
        \\fn f() !S {
        \\    return .{
        \\        .thread = try std.Thread.spawn(.{}, work, .{}),
        \\    };
        \\}
    ;
    var run = try runConcurrencyCheck(allocator, "zc104_litfield.zig", content);
    defer run.deinit(allocator);

    try expectZC104Counts(run.issues.items, 0, 0);
}

// ============================================================================
// ZA110 Tests — must-return-ref (managed container returned by value)
// ============================================================================

/// Test helper: build a one-file graph and run the errors pipeline.
fn runErrorsCheck(
    allocator: Allocator,
    path: []const u8,
    content: []const u8,
) !CFGTestRun {
    var graph = ImportGraph.init(allocator);
    errdefer graph.deinit();
    const analysis = try createTestFileAnalysis(allocator, path, content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, path), {});
    var issues = try analyzeErrors(allocator, &graph);
    errdefer deinitIssues(&issues, allocator);
    return .{ .graph = graph, .issues = issues };
}

test "ZA110: plain ownership-transfer idiom is silent (established pattern)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // `var list = ...; return list;` with no armed defer: the local is dead
    // after the copy and the caller holds the only owner. Firing here is a
    // false positive (39/39 hits on ephor itself were this idiom).
    const content =
        \\const std = @import("std");
        \\fn makeList(a: std.mem.Allocator) std.ArrayList(u8) {
        \\    var list = std.ArrayList(u8).init(a);
        \\    return list;
        \\}
    ;
    var run = try runCFGMemoryTest(allocator, "za110_basic.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        @as(usize, 0),
        countRuleIssues(run.issues.items, "za110_basic.zig", RULE_MUST_RETURN_REF),
    );
}

