    try std.testing.expect(cfg.isRuleEnabled(RULE_INTCAST_NO_BOUNDS));
}

test "ZA904: unguarded @intCast fires" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const content =
        \\fn shrink(x: u32) u8 {
        \\    return @as(u8, @intCast(x));
        \\}
    ;
